/**
 * Verifier for the `markdown-convert/` class (Tauri epic #3517, Step 05).
 *
 * The files are generated by running the Electron markdown converter in place
 * as the oracle (`apps/desktop/scripts/markdown-oracle`), which a package
 * cannot import, and reproduced byte for byte by the Rust converter
 * (`crates/memry-core/tests/markdown_*_vectors.rs`). This verifier runs no
 * oracle. It pins what the committed bytes must look like so a regeneration
 * that silently drops cases, changes an expected output or leaves a gap in the
 * coverage is a red build rather than a quiet diff:
 *
 *  1. case counts per file and per op;
 *  2. the coverage list: every frontmatter rule of protocol 12.4 has a case;
 *  3. the SHA-256 of every committed file (`vectors:digest`-style: update the
 *     constant in the same change that regenerates the file).
 */
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

import { loadVectorFile } from './vector-loader'

interface OracleCase {
  id: string
  op: string
  input: Record<string, unknown>
  expected: { status: 'ok' | 'error'; output?: unknown }
}

interface VectorFile {
  meta: { caseCount: number }
  cases: OracleCase[]
}

