const OPS_PER_FILE: Record<string, Record<string, number>> = {
  'markdown-convert/frontmatter.json': {
    split: 30,
    parse: 45,
    serialize: 41,
    dump: 158,
    load: 173,
    write: 10
  },
  'markdown-convert/markdown-class.json': { classify: 23 },
  'markdown-convert/pm-schema.json': { schema: 1, 'match-sweep': 13, 'find-wrapping': 13 },
  'markdown-convert/yxml.json': { 'yxml-read': 61, 'yxml-roundtrip': 61 },
  'markdown-convert/md-to-html.json': { 'md-to-html': 833 },
  'markdown-convert/html-to-blocks.json': { 'html-to-blocks': 129 },
  'markdown-convert/parse.json': { 'bn-parse': 833 },
  'markdown-convert/memry-parse.json': { 'memry-parse': 724 },
  'markdown-convert/serialize.json': { 'serialize-blocks': 189, 'serialize-seed': 724 },
  'markdown-convert/layer-text.json': { fn: 13066 },
  'markdown-convert/layer-markers.json': { fn: 3243 },
  'markdown-convert/layer-blocks.json': { fn: 5116 },
  'markdown-convert/layer-critic.json': { fn: 2944 },
  'markdown-convert/seed-doc.json': { 'doc-seed': 739 },
  'markdown-convert/roundtrip.json': { 'doc-serialize': 739 },
  'markdown-convert/blocks.json': { 'doc-blocks': 800 },
  'markdown-convert/serialize-doc.json': { 'doc-serialize': 498, 'doc-repair-ids': 1 },
  'markdown-convert/replace-body.json': { 'doc-replace': 44 }
}

function opCounts(file: VectorFile): Record<string, number> {
  const counts: Record<string, number> = {}
  for (const entry of file.cases) counts[entry.op] = (counts[entry.op] ?? 0) + 1
  return counts
}

describe('markdown-convert class', () => {
  describe.each(Object.entries(OPS_PER_FILE))('%s', (path, perOp) => {
    const file = loadVectorFile<VectorFile>(path)

    it('carries the pinned case counts per op', () => {
      expect(opCounts(file)).toEqual(perOp)
      expect(file.meta.caseCount).toBe(file.cases.length)
    })

    it('has unique, stable case ids and a status on every case', () => {
      const ids = file.cases.map((entry) => entry.id)
      expect(new Set(ids).size).toBe(ids.length)
      for (const entry of file.cases) {
        expect(entry.id).toMatch(/^[a-z-]+\/[a-z-]+\/[a-z0-9-]+$/)
        expect(['ok', 'error']).toContain(entry.expected.status)
      }
    })

    it('matches its committed digest', () => {
      const bytes = readFileSync(new URL(`../../test-vectors/${path}`, import.meta.url))
      expect(createHash('sha256').update(bytes).digest('hex')).toBe(DIGESTS[path])
    })
  })

  describe('frontmatter coverage (protocol 12.4)', () => {
    const file = loadVectorFile<VectorFile>('markdown-convert/frontmatter.json')
    const ids = new Set(file.cases.map((entry) => entry.id))
    const required = [
      // 12.4.1: the byte-exact split.
      'frontmatter/split/plain-block',
      'frontmatter/split/crlf-block',
      'frontmatter/split/bom-block',
      'frontmatter/split/unclosed-block',
      'frontmatter/split/no-final-newline',
      'frontmatter/split/blank-line-separator',
      // 12.4.2: the unedited and edited serialize paths.
      'frontmatter/serialize/unedited-same-content',
      'frontmatter/serialize/unedited-new-body',
      'frontmatter/serialize/edited-same-content',
      'frontmatter/serialize/crlf-new-body',
      'frontmatter/serialize/separator-kept',
      // 12.4.3: js-yaml 3.15.1 dump and load.
      'frontmatter/dump/string-long-foldable',
      'frontmatter/dump/date-midnight',
      'frontmatter/dump/map-integer-key-order',
      'frontmatter/load/timestamp-date',
      'frontmatter/load/merge-basic',
      'frontmatter/load/duplicate-key-error',
      'frontmatter/write/keys-body'
    ]

    it('has a case for every rule the list names', () => {
      expect(required.filter((id) => !ids.has(id))).toEqual([])
    })

    it('holds at least 120 dump cases', () => {
      expect(file.cases.filter((entry) => entry.op === 'dump').length).toBeGreaterThanOrEqual(120)
    })
  })

  describe('yxml coverage (protocol 12.5.0)', () => {
    const file = loadVectorFile<VectorFile>('markdown-convert/yxml.json')
    const ids = new Set(file.cases.map((entry) => entry.id))
    const required = [
      // y-prosemirror removes an element the schema cannot build, and what is left
      // of its parents with it (12.5.0).
      'yxml/read/unknown-node-drops-container',
      'yxml/read/unknown-node-keeps-sibling',
      'yxml/read/childless-table-row',
      'yxml/read/column-list-with-one-column',
      'yxml/read/code-block-rejects-marks',
      'yxml/read/unknown-mark-drops-text',
      // The read of a document BlockNote wrote loses nothing.
      'yxml/roundtrip/note-blocks-table',
      'yxml/roundtrip/note-blocks-an-empty-document',
      // Fragments y-prosemirror cannot convert at all.
      'yxml/read/text-at-fragment-root'
    ]

    it('has a case for every rule the list names', () => {
      expect(required.filter((id) => !ids.has(id))).toEqual([])
    })

    it('reads every note-blocks document', () => {
      const reads = file.cases.filter((entry) => entry.id.startsWith('yxml/read/note-blocks-'))
      expect(reads).toHaveLength(35)
    })
  })
})
